import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './Header.css';

const Header = () => {
  const [dropdownOpen, setDropdownOpen] = useState(false);

  return (
    <header className="site-header">
      <div className="container">
        <div className="logo-container">
          <Link to="/" className="logo-text">LOGO</Link>
        </div>
        <nav className="site-nav">
          <ul className="nav-links">
            <li><Link to="/about-us">About us</Link></li>
            <li><Link to="/financial-services">Financial services</Link></li>
            <li><Link to="/bajaj-broking">Bajaj Broking</Link></li>

            <li 
              className="nav-dropdown" 
              onMouseEnter={() => setDropdownOpen(true)} 
              onMouseLeave={() => setDropdownOpen(false)}
            >
              <span className="dropdown-trigger">Other services ▼</span>
              <ul className={`dropdown-menu ${dropdownOpen ? 'open' : ''}`}>
                <li><Link to="/coal-transporting">Coal Transporting</Link></li>
                <li><Link to="/accounting-services">Accounting services</Link></li>
              </ul>
            </li>

            <li><Link to="/contact-us">Contact us</Link></li>
          </ul>
        </nav>
      </div>
    </header>
  );
};

export default Header;
